window.PokemonBattleAudio=(()=>{let ctx,enabled=true;function unlock(){try{ctx??=new (window.AudioContext||window.webkitAudioContext)();ctx.resume();}catch{}}function play(type,hit=false){if(!enabled||!ctx||ctx.state!=='running')return;const t=ctx.currentTime,d=hit?.18:.6,g=ctx.createGain();g.gain.setValueAtTime(hit?.12:.07,t);g.gain.exponentialRampToValueAtTime(.001,t+d);g.connect(ctx.destination);
 const osc=ctx.createOscillator();osc.type=type==='electric'?'sawtooth':type==='steel'?'triangle':'sine';const freq=hit?130:({water:450,fire:110,electric:180,grass:700,fighting:160,normal:160,psychic:550,dark:90,steel:1450})[type]||160;osc.frequency.setValueAtTime(freq,t);osc.frequency.exponentialRampToValueAtTime(hit?45:freq*.45,t+d);osc.connect(g);osc.start(t);osc.stop(t+d);
 const buffer=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*d),ctx.sampleRate),a=buffer.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*(type==='fire'&&i%1200<100?1:.5);const n=ctx.createBufferSource(),filter=ctx.createBiquadFilter();n.buffer=buffer;filter.type=type==='water'?'bandpass':'lowpass';filter.frequency.value=hit?800:type==='electric'?3500:type==='water'?1600:650;n.connect(filter);filter.connect(g);n.start(t);n.stop(t+d);
}return {unlock,play,toggle(){enabled=!enabled;return enabled;},get enabled(){return enabled;}};})();
